    {
      "Asymptote freezer showed less well-to-well difference with p = 0.83.": "p = 0.83"
    },
    {
      "Standard deviation in Asymptote freezer was 0.73 compared to 1.6 in 96-well.": "standard deviation 0.73"
    },
    {
      "Overall dispersion was 36% lower in the Asymptote freezer.": "36% lower dispersion"
    }
  ]
}

